        {
            string[] relParts = relName.Split(' ');
            relatives.Add(new
            {
                FirstName = relParts[0],
                LastName = relParts.Length > 1 ? relParts[relParts.Length - 1] : "",
                Relationship = relationshipTypes[i]
            });
        }
    }

    results.Add(new
    {
        FirstName = firstName,
        LastName = lastName,
        Birthday = birthday.ToString("yyyy-MM-dd"),
        Age = age,
        Relatives = relatives
    });
}

