        string[] relParts = relName.Split(' ');
        reatives.Add(new
        {
            FirstName = relParts[0],
            LastName = relParts.Length > 1 ? relParts[relParts.Length - 1] : "",
            Relationship = labels[i]
        });
    }

    resultList.Add(new
    {
        FirstName = firstName,
        LastName = lastName,
        Birthday = birthdayStr,
        Age = age,
        Relatives = relatives
    });
}

var options = new JsonSerializerOptions { WriteIndented = true };
